const input = $input.first().json;

let text = '', user = '', ts = '', channel = '';

if (input.type === 'reaction_added') {
  text = `[Reaction] :${input.reaction}: on message in ${input.item?.channel}`;
  user = input.user || '';
  ts = input.item?.ts || '';
  channel = input.item?.channel || '';
} else {
  text = (input.text || '').replace(/^<@[A-Z0-9]+>\s*/i, '').trim();
  user = input.user || '';
  ts = input.ts || '';
  channel = input.channel || '';
}

return [{ json: { text, user, ts, channel } }];

const plan = $input.first().json.output;
const trigger = $('Normalise Trigger Payload').first().json;
return [{ json: { ...plan, classification: 'AD_HOC_QUERY', original_message: trigger.text, slack_user: trigger.user, slack_ts: trigger.ts, slack_channel: trigger.channel } }];

const raw = $input.first().json.output || $input.first().json.text || '';
let plan = {};
try {
  const match = raw.match(/\{[\s\S]*\}/);
  plan = match ? JSON.parse(match[0]) : {};
} catch(e) {
  plan = { summary: 'Could not parse AI response', raw_output: raw };
}
const trigger = $('Normalise Trigger Payload').first().json;
return [{ json: { ...plan, classification: 'PIPELINE_REQUEST', original_message: trigger.text, slack_user: trigger.user, slack_ts: trigger.ts, slack_channel: trigger.channel } }];

