const body = $input.first().json.body;
const action = body.action;
const sql = body.sql || '';
return [{ json: { action, sql } }];

const chResponse = $input.first().json;
const plan = $('Parse Ad-hoc Plan JSON').first().json;
const format = plan.output_format || 'table';
let formatted = '';

try {
  if (chResponse.data && chResponse.meta) {
    const cols = chResponse.meta.map(m => m.name);
    const rows = chResponse.data;

    if (format === 'csv') {
      formatted = [cols.join(','), ...rows.map(r => r.join(','))].join('\n');
    } else {
      const widths = cols.map((col, i) =>
        Math.max(col.length, ...rows.map(r => String(r[i] ?? '').length))
      );
      const pad = (val, w) => String(val ?? '').padEnd(w);
      const header = cols.map((c, i) => pad(c, widths[i])).join('  ');
      const sep   = widths.map(w => '-'.repeat(w)).join('  ');
      const body  = rows.map(r => r.map((v, i) => pad(v, widths[i])).join('  ')).join('\n');
      formatted = `${header}\n${sep}\n${body}`;
    }
  } else {
    formatted = JSON.stringify(chResponse, null, 2);
  }
} catch(e) {
  formatted = JSON.stringify(chResponse, null, 2);
}

const rowCount = chResponse.rows || chResponse.data?.length || 0;
return [{ json: {
  formatted, rowCount, format, plan,
  rawData: chResponse.data || [],
  rawMeta: chResponse.meta || []
} }];

